function StaffTab() {
  const staff = [
    {init:"KC", name:'Kenneth "K.C." Borden', title:"Executive Director", sub:"Kansas City Chapter, NECA", photo:"data:image/jpeg;base64,"},
    {init:"JP", name:"Julie Perkins", title:"Assistant Executive Director", sub:"Kansas City Chapter, NECA", photo:"data:image/jpeg;base64,"},
    {init:"KM", name:"Kimberly Mullendore", title:"Executive Assistant", sub:"Kansas City Chapter, NECA", photo:null},
  ];
  const board = [
    {init:"TY", name:"Troy Yates",       title:"Governor"},
    {init:"MT", name:"Marc Tower",       title:"President"},
    {init:"JP", name:"Joseph Privitera", title:"Vice President"},
    {init:"RB", name:"Rita Baslock",     title:"Treasurer"},
    {init:"RB", name:"Ryan Blake",       title:"Director"},
    {init:"JG", name:"Jeff Gardner",     title:"Director"},
    {init:"CH", name:"Chris Head",       title:"Director"},
    {init:"JK", name:"Jason King",       title:"Director"},
    {init:"JP", name:"Jerry Prochko",    title:"Director"},
    {init:"MQ", name:"Michael Quarles",  title:"Director"},
    {init:"JR", name:"John Rolls",       title:"Director"},
    {init:"MW", name:"Mark Wiswell",     title:"Joplin Chairman"},
    {init:"DS", name:"Don Stilley",      title:"Springfield Chairman"},
    {init:"SD", name:"Steve Dragoo",     title:"St. Joseph Chairman"},
  ];
  const Av = ({ i, bg, bc, tc }) => (
    <div style={{ width: 42, height: 42, borderRadius: "50%", background: bg, border: `1px solid ${bc}`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 700, color: tc, flexShrink: 0 }}>{i}</div>
  );
  return (
    <div style={{ padding: "14px 14px 20px" }}>
      <SectionLabel>Staff</SectionLabel>
      {staff.map((m) => (
        <div key={m.init} style={cardStyle}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            {m.photo
              ? <img src={m.photo} alt={m.name} style={{ width: 48, height: 48, borderRadius: "50%", objectFit: "cover", flexShrink: 0, border: "2px solid #bfdbfe" }} />
              : <Av i={m.init} bg="#dbeafe" bc="#bfdbfe" tc="#1e3a5f" />
            }
            <div>
              <div style={{ fontSize: 13, fontWeight: 700, color: "#111827" }}>{m.name}</div>
              <div style={{ fontSize: 11, fontWeight: 600, color: "#185FA5", marginTop: 1 }}>{m.title}</div>
              <div style={{ fontSize: 11, color: "#6b7280", marginTop: 1 }}>{m.sub}</div>
            </div>
          </div>
        </div>
      ))}
      <SectionLabel mt={6}>Board of directors</SectionLabel>
      {board.map((b, i) => (
        <div key={i} style={cardStyle}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <Av i={b.init} bg="#d1fae5" bc="#6ee7b7" tc="#064e3b" />
            <div>
              <div style={{ fontSize: 13, fontWeight: 600, color: "#111827" }}>{b.name}</div>
              <div style={{ fontSize: 11, fontWeight: 600, color: "#185FA5", marginTop: 1 }}>{b.title}</div>
            </div>
          </div>
        </div>
      ))}

    </div>
  );
}

function ContactTab() {
  const rows = [
    ["Address","800 E 101st Terrace, Suite 220\nKansas City, MO 64131"],
    ["Phone","(816) 753-7444"],
    ["Email","info@kcneca.com"],
    ["Office hours","Mon–Fri, 8:00 AM – 5:00 PM"],
  ];
  return (
    <div style={{ padding: "14px 14px 20px" }}>
      <div style={cardStyle}>
        <div style={{ fontSize: 15, fontWeight: 700, color: "#111827", marginBottom: 12, textAlign: "center" }}>Kansas City Chapter, NECA</div>
        {rows.map(([label, val], i) => (
          <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 0", borderBottom: i < rows.length - 1 ? "1px solid #e5e7eb" : "none" }}>
            <span style={{ fontSize: 12, fontWeight: 500, color: "#6b7280" }}>{label}</span>
            <span style={{ fontSize: 13, fontWeight: 600, color: "#111827", textAlign: "right" }}>
              {val.split("\n").map((line, i) => <span key={i} style={{ display: "block" }}>{line}</span>)}
            </span>
          </div>
        ))}
      </div>

    </div>
  );
}

export default function App() {
  const [tab, setTab] = useState("home");
  const navItems = [
    { id: "home", label: "Home" },
    { id: "cba", label: "Agreements" },
    { id: "meetings", label: "Meetings" },
    { id: "staff", label: "Staff/Board" },
    { id: "contact", label: "Contact" },
  ];
  const content = {
    home: <HomeTab setTab={setTab} />,
    cba: <CBATab />,
    meetings: <MeetingsTab />,
    staff: <StaffTab />,
    contact: <ContactTab />,
  };
  return (
    <div style={{ background: "#e5e7eb", borderRadius: 24, padding: 16, maxWidth: 360, margin: "0 auto" }}>
      <div style={{ background: "#fff", borderRadius: 16, border: "1px solid #d1d5db", overflow: "hidden", minHeight: 600, display: "flex", flexDirection: "column" }}>
        <div style={{ background: "#0C447C", padding: "0", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <img src="data:image/jpeg;base64," alt="Kansas City Chapter NECA" style={{ width: "100%", height: "auto", display: "block" }} />
        </div>
        <div style={{ flex: 1, overflowY: "auto", background: "#f9fafb" }}>
          {content[tab]}
        </div>
        <div style={{ display: "flex", background: "#ffffff", borderTop: "1px solid #e5e7eb", padding: "6px 0 10px" }}>
          {navItems.map(item => {
            const active = tab === item.id;
            return (
              <button key={item.id} onClick={() => setTab(item.id)}
                style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 2, cursor: "pointer", border: "none", background: "none", padding: "4px 2px" }}>
                <div style={{ width: 24, height: 3, borderRadius: 2, background: active ? "#0C447C" : "transparent", marginBottom: 1 }} />
                <span style={{ fontSize: 10, fontWeight: active ? 700 : 500, color: active ? "#0C447C" : "#6b7280" }}>{item.label}</span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}
